async (page) => {
  // wrench = editSettings → in create mode opens the drawer form
  await page.locator('.q-dialog .post--control').first().click();
  await page.waitForTimeout(2500);
  const drawerOpen = await page.locator('.q-dialog .q-drawer').isVisible().catch(() => false);
  // find the Title input inside the drawer form and type
  const titleInput = page.locator('.q-dialog .q-drawer input').first();
  const inputCount = await page.locator('.q-dialog .q-drawer input').count();
  if (inputCount) {
    await titleInput.fill('Migration Verified');
    await page.waitForTimeout(1500);
  }
  const playerTitle = await page.locator('.q-dialog .post--title').innerText().catch(() => '(no title el)');
  await page.screenshot({ path: 'tmp/screenshots/create-drawer.png' });
  return { drawerOpen, inputCount, playerTitle };
}

