async (page) => {
  const item = page.locator('.postItem--wrap').first();
  await item.hover();
  await page.waitForTimeout(800);
  const menuBtn = page.locator('.post--sortable-drag-handle').first();
  const btnVisible = await menuBtn.evaluate((el) => getComputedStyle(el).visibility);
  await menuBtn.click();
  await page.waitForTimeout(1200);
  const menuOpen = await page.locator('.q-menu').count();
  const menuText = menuOpen ? (await page.locator('.q-menu').first().innerText()).replace(/\n+/g, ' | ').slice(0, 120) : '';
  await page.screenshot({ path: 'tmp/screenshots/menu-open.png' });
  // close via Escape (menuShown v-model writes false)
  await page.keyboard.press('Escape');
  await page.waitForTimeout(800);
  const menuClosed = (await page.locator('.q-menu').count()) === 0;
  return { btnVisible, menuOpen, menuText, menuClosed };
}

