// TEMP benchmark harness — deleted after the docs numbers are refreshed.
// Every instance escapes into a pre-allocated array; a post-timing pass
// touches the array so no allocation is elidable. Median of runs reported.
import { describe, it } from 'vitest';
import { computed, reactive, ref, proxyRefs } from 'vue';
import { Reactive } from '../Reactive';
import { ivue } from '../ivue';

class $Box {
  get width() {
    return ref(1);
  }
  get height() {
    return ref(2);
  }
  get area() {
    return this.width.value * this.height.value;
  }
  grow() {
    return this.width.value + 1;
  }
}
const Box = Reactive($Box);

class PlainBox {
  width = 1;
  height = 2;
  get area() {
    return this.width * this.height;
  }
  grow() {
    return this.width + 1;
  }
}

const useBox = () => {
  const width = ref(1);
  const height = ref(2);
  const area = computed(() => width.value * height.value);
  const grow = () => width.value + 1;
  return { width, height, area, grow };
};

class $V1Box {
  get width() {
    return ref(1);
  }
  get height() {
    return ref(2);
  }
  get area() {
    return this.width.value * this.height.value;
  }
  grow() {
    return this.width.value + 1;
  }
}

function median(values: number[]): number {
  const sorted = [...values].sort((a, b) => a - b);
  return sorted[Math.floor(sorted.length / 2)];
}

function benchCreation(label: string, count: number, make: () => unknown, runs = 7) {
  const times: number[] = [];
  for (let run = 0; run < runs; run++) {
    const instances = new Array(count);
    const t0 = performance.now();
    for (let i = 0; i < count; i++) instances[i] = make();
    const t1 = performance.now();
    // liveness pass — every element observed after timing
    let alive = 0;
    for (let i = 0; i < count; i += 997) if (instances[i]) alive++;
    if (alive < 0) throw new Error('unreachable');
    times.push(t1 - t0);
  }
  console.log(`${label}: ${median(times).toFixed(1)} ms (median of ${runs})`);
  return median(times);
}

function benchRead(label: string, read: () => number, iterations = 10_000_000, runs = 5) {
  const times: number[] = [];
  let sum = 0;
  for (let run = 0; run < runs; run++) {
    const t0 = performance.now();
    for (let i = 0; i < iterations; i++) sum += read();
    times.push(performance.now() - t0);
  }
  if (sum < 0) throw new Error('unreachable');
  const nsPerOp = (median(times) * 1e6) / iterations;
  console.log(`${label}: ${nsPerOp.toFixed(1)} ns/op`);
  return nsPerOp;
}

describe('docs benchmark refresh', () => {
  it('creation — 100k and 1M', () => {
    const V1Box = ivue.toReactive
      ? null
      : null; // placeholder guard, v1 used below via ivue()
    for (const count of [100_000, 1_000_000]) {
      console.log(`\n=== creation, ${count.toLocaleString()} instances ===`);
      benchCreation('ivue new Box()', count, () => new Box());
      benchCreation('reactive(new PlainBox())', count, () => reactive(new PlainBox()));
      benchCreation('composable useBox()', count, () => useBox());
      if (count === 100_000) {
        benchCreation('v1 ivue($V1Box)', count, () => ivue($V1Box));
      }
    }
  }, 600_000);

  it('template boundary — per-read costs', () => {
    const instance: any = new Box();
    instance.width; // materialize
    const unwrapped: any = proxyRefs(instance);
    const wrapped: any = reactive(instance);
    const native = new PlainBox();
    console.log('\n=== per-read, raw ivue instance ===');
    benchRead('raw plain-derived getter (area)', () => instance.area);
    benchRead('raw ref-getter access (.width)', () => (instance.width ? 1 : 0));
    benchRead('raw method ACCESS (.grow)', () => (instance.grow ? 1 : 0));
    benchRead('raw method CALL (.grow())', () => instance.grow());
    const grow = instance.grow;
    benchRead('HOISTED method CALL (grow())', () => grow());
    console.log('\n=== per-read, shallow unwrap proxy ===');
    benchRead('unwrap plain-derived getter', () => unwrapped.area);
    benchRead('unwrap ref read (.width)', () => unwrapped.width);
    benchRead('unwrap method access', () => (unwrapped.grow ? 1 : 0));
    console.log('\n=== per-read, reactive() wrapper ===');
    benchRead('reactive plain-derived getter', () => wrapped.area);
    benchRead('reactive ref read (.width)', () => wrapped.width);
    benchRead('reactive method access', () => (wrapped.grow ? 1 : 0));
    console.log('\n=== native baselines ===');
    benchRead('native class getter (area)', () => native.area);
    benchRead('native method CALL', () => native.grow());
  }, 600_000);
});

